package com.ruoyi.paicli.controller;

import com.ruoyi.common.annotation.Log;
import com.ruoyi.common.enums.BusinessType;
import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.paicli.service.*;
import com.ruoyi.paicli.domain.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import tools.jackson.core.type.TypeReference;
import java.util.*;

@RestController @RequestMapping("/paicli/v1")
@ConditionalOnProperty(prefix="paicli",name="enabled",havingValue="true")
public class PcConnectionController extends PcControllerSupport {
    private final PcConnectionService connections;private final PcAccess access;private final PcKnowledgeService knowledge;
    public PcConnectionController(PcStore s,PcConnectionService c,PcAccess a,PcKnowledgeService k){super(s);connections=c;access=a;knowledge=k;}
    @GetMapping({"/providers","/models","/mcp","/skills"}) @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult list(jakarta.servlet.http.HttpServletRequest r,@RequestParam(required=false) Long workspaceId){return AjaxResult.success(connections.list(kind(r),actor(),workspaceId));}
    private String kind(jakarta.servlet.http.HttpServletRequest request){return request.getRequestURI().substring(request.getRequestURI().lastIndexOf('/')+1);}
    @PutMapping("/providers") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") @Log(title="PaiCLI供应商配置",businessType=BusinessType.UPDATE,isSaveRequestData=false)
    public AjaxResult provider(@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.save("providers",actor(),key,version(v),input));}
    @PostMapping({"/models","/mcp","/skills"}) @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") @Log(title="PaiCLI连接配置",businessType=BusinessType.INSERT,isSaveRequestData=false)
    public AjaxResult save(jakarta.servlet.http.HttpServletRequest r,@RequestHeader(value="If-Match",defaultValue="0") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.save(kind(r),actor(),key,version(v),input));}
    @PostMapping("/providers/{id}/refresh") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult refresh(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key){return AjaxResult.success(connections.action("providers",id,actor(),key,version(v),Map.of("action","REFRESH")));}
    @PostMapping("/providers/{id}/verify") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')")
    @Log(title="PaiCLI Sub2API兼容验证",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false)
    public AjaxResult verifyProvider(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.verifyProvider(id,actor(),key,version(v),input));}
    @PostMapping("/mcp/{id}/actions") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") @Log(title="PaiCLI MCP控制",businessType=BusinessType.UPDATE)
    public AjaxResult mcp(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.action("mcp",id,actor(),key,version(v),input));}
    @GetMapping("/mcp/{id}/logs") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult logs(@PathVariable long id){return AjaxResult.success(connections.get("mcp",id,actor()).getOrDefault("logs",List.of()));}
    @GetMapping("/mcp/{id}/{content:resource|prompt}") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult content(@PathVariable long id,@PathVariable String content,@RequestParam String reference){return AjaxResult.success(connections.mcpContent(id,actor(),content,reference));}
    @PostMapping("/mcp/{id}/contents") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") @Log(title="PaiCLI MCP内容读取",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false)
    public AjaxResult readContent(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.mcpRead(id,actor(),key,version(v),input));}
    @PostMapping("/browser/{id}/actions") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult browserAction(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.action("browser",id,actor(),key,version(v),input));}
    @GetMapping("/browser") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult browser(@RequestParam long workspaceId){var rows=connections.list("browser",actor(),workspaceId);return AjaxResult.success(rows.isEmpty()?Map.of("workspaceId",String.valueOf(workspaceId),"mode","DISCONNECTED","version",0,"connected",false):rows.get(0));}
    @PutMapping("/browser") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult browser(@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.browser(actor(),key,version(v),input));}
    @PostMapping("/browser/probe") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult probe(@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){long workspace=PcJson.number(input,"workspaceId");access.workspace(workspace,actor(),false);PcRecord r=store.mapper.findKey(PcTable.BROWSER_CONFIG,"workspace:"+workspace,false);if(r==null)throw PcException.invalid("请先配置浏览器");return AjaxResult.success(connections.action("browser",r.getId(),actor(),key,r.getVersion(),Map.of("action","PROBE")));}
    @GetMapping("/skills/{id}") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult skill(@PathVariable long id){return AjaxResult.success(connections.get("skills",id,actor()));}
    @PutMapping("/skills/{id}") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult skill(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.action("skills",id,actor(),key,version(v),input));}
    @PostMapping("/skills/reload") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult reload(@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){long workspace=PcJson.number(input,"workspaceId");access.admin(workspace,actor());return AjaxResult.success(connections.reloadSkills(actor(),key,workspace));}
    @GetMapping("/wechat") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult wechat(@RequestParam long workspaceId){var rows=connections.list("wechat",actor(),workspaceId);return AjaxResult.success(rows.isEmpty()?null:rows.get(0));}
    @PostMapping("/wechat/setup") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult setupWechat(@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.setupWechat(actor(),key,PcJson.number(input,"workspaceId")));}
    @PutMapping("/wechat/{id}/binding") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult bindWechat(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.bindWechat(actor(),id,version(v),key,input));}
    @PutMapping("/wechat/{id}/policy") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") @Log(title="PaiCLI微信策略",businessType=BusinessType.UPDATE,isSaveRequestData=false)
    public AjaxResult wechatPolicy(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.saveWechatPolicy(actor(),id,version(v),key,input));}
    @PostMapping("/wechat/{id}/actions") @PreAuthorize("@ss.hasPermi('paicli:connection:manage')") public AjaxResult wechat(@PathVariable long id,@RequestHeader("If-Match") String v,@RequestHeader("Idempotency-Key") String key,@RequestBody Map<String,Object> input){return AjaxResult.success(connections.action("wechat",id,actor(),key,version(v),input));}
    @GetMapping("/tools") @PreAuthorize("@ss.hasPermi('paicli:connection:read')") public AjaxResult tools(@RequestParam long workspaceId)throws java.io.IOException{access.workspace(workspaceId,actor(),false);List<Map<String,Object>> tools;try(var in=getClass().getResourceAsStream("/paicli/tools-v1.json")){tools=new tools.jackson.databind.ObjectMapper().readValue(in,new TypeReference<List<Map<String,Object>>>(){});}var runners=store.mapper.list(PcTable.RUNNER,workspaceId,null,null,"ONLINE");var policy=store.data(store.mapper.findKey(PcTable.POLICY_VERSION,"workspace:"+workspaceId,false));for(var tool:tools){Object capability=tool.get("capability");boolean enabled=policy.get("allowedCapabilities") instanceof List<?> allowed&&allowed.contains(capability)&&runners.stream().anyMatch(r->store.data(r).get("capabilities") instanceof List<?> caps&&caps.contains(capability));tool.put("enabled",enabled);if(!enabled)tool.put("unavailableReason","当前策略或在线Runner没有该能力");}for(var mcp:connections.list("mcp",actor(),workspaceId))if(mcp.get("tools") instanceof List<?> defs)for(Object def:defs)if(def instanceof Map<?,?> map){Map<String,Object> t=new LinkedHashMap<>();map.forEach((k,v)->t.put(String.valueOf(k),v));t.put("source","MCP");t.put("name","mcp__"+mcp.get("name")+"__"+t.get("name"));t.put("enabled","READY".equals(mcp.get("status"))&&Objects.equals(mcp.get("configHash"),mcp.get("trustedHash")));t.put("approvalRequired",true);tools.add(t);}return AjaxResult.success(tools);}
}
